function getCommentsMembersOnlyRestriction(
  claimId: string | undefined,
  channelClaimId: string | undefined,
  isLivestream: boolean | undefined,
  doFetchCreatorSettings: (channelId: string) => Promise<any>
) {
  const isAnonymous = claimId && !channelClaimId;

  if (isAnonymous) {
    return false;
  }

  return (
    channelClaimId &&
    doFetchCreatorSettings(channelClaimId)
      .then((cs: SettingsResponse) => (isLivestream ? cs.livestream_chat_members_only : cs.comments_members_only))
      .catch(() => undefined)
  );
}

type TipParams = {
  tipAmount: number;
  tipChannelName: string;
  channelClaimId: string;
};
type ArTipParams = {
  tipAmountTwoPlaces: number;
  tipChannelName: string;
  channelClaimId: string;
  recipientAddress: string;
  currency: 'USD' | 'AR';
};
type UserParams = {
  activeChannelName: string | null | undefined;
  activeChannelId: string | null | undefined;
};
type Props = {
  bottom: boolean;
  embed?: boolean;
  isNested: boolean;
  isReply: boolean;
  isLivestream?: boolean;
  parentId: string;
  shouldFetchComment: boolean;
  uri: string;
  disableInput?: boolean;
  onSlimInputClose?: () => void;
  setQuickReply: (arg0: any) => void;
  onCancelReplying?: () => void;
  onDoneReplying?: () => void;
  textInjection?: string;
  supportDisabled?: boolean;
};
export function CommentCreate(props: Props) {
  const {
    bottom,
    embed,
    isNested,
    isReply,
    isLivestream,
    parentId,
    shouldFetchComment,
    uri,
    disableInput,
    onSlimInputClose,
    setQuickReply,
    onCancelReplying,
    onDoneReplying,
    textInjection,
  } = props;

  const fileUri = React.useContext(AppContext)?.uri;
  const dispatch = useAppDispatch();
  const claim = useAppSelector((state) => selectClaimForUri(state, uri));
  const supportDisabled = useAppSelector((state) =>
    makeSelectTagInClaimOrChannelForUri(uri, DISABLE_SUPPORT_TAG)(state)
  );
  const { claim_id: claimId, name, signing_channel: channel } = claim || {};
  const channelClaimId = getChannelIdFromClaim(claim);
  const tipChannelName = channel ? channel.name : name;
  const activeChannelClaim = useAppSelector(selectActiveChannelClaim);
  const {
    claim_id: activeChannelClaimId,
    name: activeChannelName,
    canonical_url: activeChannelUrl,
  } = activeChannelClaim || {};
  const tipData = useAppSelector((state) => selectArweaveTipDataForId(state, channelClaimId));
  const canReceiveTips = tipData?.status === 'active' && tipData?.default;
  const hasChannels = useAppSelector(selectHasChannels);
  const isFetchingChannels = useAppSelector(selectFetchingMyChannels);
  const isFetchingCreatorSettings = useAppSelector(selectFetchingCreatorSettings);
  const claimIsMine = useAppSelector((state) => selectClaimIsMine(state, claim));
  const myChannelClaimIds = useAppSelector(selectMyChannelClaimIds);
  const myCommentedChannelIds = useAppSelector((state) => selectMyCommentedChannelIdsForId(state, claim?.claim_id));
  const preferredCurrency = useAppSelector(selectPreferredCurrency);
  const channelSettings = useAppSelector((state) => state.comments.settingsByChannelId[channelClaimId]);
  const chatCommentsRestrictedToChannelMembers = Boolean(
    useAppSelector((state) => selectedRestrictedCommentsChatTagForUri(state, uri))
  );
  const userHasMembersOnlyChatPerk = useAppSelector((state) =>
    selectUserIsMemberOfMembersOnlyChatForCreatorId(state, channelClaimId)
  );
  const commentSettingDisabled = useAppSelector((state) =>
    selectCommentsDisabledSettingForChannelId(state, channelClaimId)
  );
  const isLivestreamChatMembersOnly = Boolean(
    useAppSelector((state) => selectLivestreamChatMembersOnlyForChannelId(state, channelClaimId))
  );
  const areCommentsMembersOnly = Boolean(
    useAppSelector((state) => selectMembersOnlyCommentsForChannelId(state, channelClaimId))
  );
  const hasPremiumPlus = useAppSelector(hasLegacyOdyseePremium);
  const recipientArweaveTipInfo = useAppSelector((state) => selectArweaveTipDataForId(state, channelClaimId));
  const arweaveTippingError = useAppSelector((state) => selectArweaveTippingErrorForId(state, channelClaimId));

  const doCommentCreate = React.useCallback(
    (uri: string, isLivestream: boolean | undefined, params: CommentSubmitParams) =>
      dispatch(doCommentCreateAction(uri, isLivestream, params)),
    [dispatch]
  );
  const doFetchCreatorSettings = React.useCallback(
    (channelId: string) => dispatch(doFetchCreatorSettingsAction(channelId)),
    [dispatch]
  );
  const doToast = React.useCallback((params: ToastParams) => dispatch(doToastAction(params)), [dispatch]);
  const doCommentById = React.useCallback(
    (commentId: string, toastIfNotFound: boolean) => dispatch(doCommentByIdAction(commentId, toastIfNotFound)),
    [dispatch]
  );
  const doSendCashTip = React.useCallback(
    (
      tipParams: TipParams,
      anonymous: boolean,
      userParams: UserParams,
      claimId: string,
      stripe: string | null | undefined,
      preferredCurrency: string,
      cb: (arg0: any) => void
    ) => dispatch(doSendCashTipAction(tipParams, anonymous, userParams, claimId, stripe, preferredCurrency, cb)),
    [dispatch]
  );
  const doArTip = React.useCallback(
    (
      tipParams: ArTipParams,
      anonymous: boolean,
      userParams: UserParams,
      claimId: string,
      stripe: string | null | undefined
    ) => dispatch(doArTipAction(tipParams, anonymous, userParams, claimId, stripe)),
    [dispatch]
  );
  const doOpenModal = React.useCallback(
    (id: string, modalProps: any) => dispatch(doOpenModalAction(id, modalProps)),
    [dispatch]
  );
  const doFetchMyCommentedChannels = React.useCallback(
    (claimId: string | null | undefined) => dispatch(doFetchMyCommentedChannelsAction(claimId)),
    [dispatch]
  );
  const doTipAccountCheckForUri = React.useCallback(
    (uri: string) => dispatch(doTipAccountCheckForUriAction(uri)),
    [dispatch]
  );
  const navigate = useNavigate();
  const { pathname } = useLocation();
  const { activeArStatus } = useArStatus();
  const isMobile = useIsMobile();
  const buttonRef = React.useRef<HTMLButtonElement | null>(null);
  const slimInputButtonRef = React.useRef<HTMLDivElement | null>(null);
  const [isSubmitting, setSubmitting] = React.useState(false);
  const [commentFailure, setCommentFailure] = React.useState(false);
  const [successTip, setSuccessTip] = React.useState({
    txid: undefined,
    tipAmount: undefined,
  });
  const [tipSelectorOpen, setTipSelector] = React.useState<boolean>(false);
  const [isReviewingSupportComment, setReviewingSupportComment] = React.useState<boolean>(false);
  const [isReviewingStickerComment, setReviewingStickerComment] = React.useState<boolean>(false);
  const [selectedSticker, setSelectedSticker] = React.useState<any>(undefined);
  const [tipAmount, setTipAmount] = React.useState(1);
  // const [convertedAmount, setConvertedAmount] = React.useState();
  const [commentValue, setCommentValue] = React.useState('');

  const [activeTab, setActiveTab] = React.useState<string | undefined>();
  const [tipError, setTipError] = React.useState<any>();
  const [deletedComment, setDeletedComment] = React.useState(false);
  const [showSelectors, setShowSelectors] = React.useState<{
    tab: any;
    open: boolean;
  }>({
    tab: undefined,
    open: false,
  });
  const [disableReviewButton, setDisableReviewButton] = React.useState<any>();
  const [exchangeRate, setExchangeRate] = React.useState<number | undefined>();
  const [tipModalOpen, setTipModalOpen] = React.useState<boolean | undefined>(undefined);
  const charCount = commentValue ? commentValue.length : 0;
  const hasNothingToSumbit = !commentValue.length && !selectedSticker;
  const minSuper = (channelSettings && channelSettings.min_tip_amount_super_chat) || 0;
  const minTip = (channelSettings && channelSettings.min_tip_amount_comment) || 0;
  const minAmount = minTip || minSuper || 0;
  const minUSDSuper = (channelSettings && channelSettings.min_usdc_tip_amount_super_chat) || 0;
  const minUSDTip = (channelSettings && channelSettings.min_usdc_tip_amount_comment) || 0;
  const minUSDAmount = minUSDTip || minUSDSuper || 0;
  // Convert legacy LBC minimums to 1 cent USD if they exist
  const legacyMinAsUSD = minAmount > 0 ? 0.01 : 0;
  // For regular comments: only check minUSDTip (and legacy minTip)
  // For hyperchat comments: check minUSDAmount (includes both minUSDTip and minUSDSuper)
  const isHyperchat = activeTab === TAB_USD;
  const minAmountMet =
    claimIsMine || (isHyperchat ? tipAmount >= (minUSDAmount || legacyMinAsUSD) : !(minUSDTip || minTip));
  // Regular comments are blocked only if minUSDTip/minTip is set
  const stickerPrice = selectedSticker && selectedSticker.price;
  const tipSelectorError = tipError || disableReviewButton;
  const disabled =
    commentSettingDisabled ||
    deletedComment ||
    isSubmitting ||
    isFetchingChannels ||
    isFetchingCreatorSettings ||
    hasNothingToSumbit ||
    !minAmountMet ||
    disableInput;
  const minUSDAmountRef = React.useRef(minUSDAmount);
  minUSDAmountRef.current = minUSDAmount;
  const cursorPosRef = React.useRef<number | null>(null);
  React.useEffect(() => {
    const cls = isReply ? 'create__reply' : 'create__comment';
    const textarea = document.querySelector<HTMLTextAreaElement>(`.${cls} textarea, textarea.${cls}, textarea#${cls}`);
    if (!textarea) return;
    const saveCursor = () => {
      cursorPosRef.current = textarea.selectionStart;
    };
    textarea.addEventListener('keyup', saveCursor);
    textarea.addEventListener('click', saveCursor);
    textarea.addEventListener('blur', saveCursor);
    return () => {
      textarea.removeEventListener('keyup', saveCursor);
      textarea.removeEventListener('click', saveCursor);
      textarea.removeEventListener('blur', saveCursor);
    };
  });
  const addEmoteToComment = React.useCallback(
    (emote: string) => {
      const cls = isReply ? 'create__reply' : 'create__comment';
      const textarea = document.querySelector<HTMLTextAreaElement>(
        `.${cls} textarea, textarea.${cls}, textarea#${cls}`
      );
      const pos = cursorPosRef.current ?? textarea?.value?.length ?? 0;

      setCommentValue((prev) => {
        const before = prev.substring(0, pos);
        const after = prev.substring(pos);
        const spaceBefore = before.length > 0 && before.charAt(before.length - 1) !== ' ' ? ' ' : '';
        const spaceAfter = after.length > 0 && after.charAt(0) !== ' ' ? ' ' : '';
        const insertion = spaceBefore + emote + spaceAfter;
        const newPos = pos + insertion.length;
        requestAnimationFrame(() => {
          if (textarea) {
            textarea.focus();
            textarea.setSelectionRange(newPos, newPos);
          }
        });
        return before + insertion + after;
      });
    },
    [isReply]
  );
  const handleSelectSticker = React.useCallback(
    (sticker: any) => {
      setSelectedSticker(sticker);
      setReviewingStickerComment(true);
      setTipAmount(sticker.price || 0);
      setShowSelectors((prev) => ({
        tab: prev.tab || undefined,
        open: false,
      }));
      // added this here since selecting a sticker can cause scroll issues
      if (onSlimInputClose) onSlimInputClose();

      if (sticker.price && sticker.price > 0) {
        setActiveTab(TAB_USD);
        setTipSelector(true);
      }
    },
    [onSlimInputClose]
  );
  const commentSelectorsProps = React.useMemo(() => {
    return {
      claimIsMine: Boolean(claimIsMine),
      addEmoteToComment,
      handleSelectSticker,
      isOpen: showSelectors.open,
      openTab: showSelectors.tab || undefined,
    };
  }, [claimIsMine, addEmoteToComment, handleSelectSticker, showSelectors.open, showSelectors.tab]);
  const submitButtonProps = {
    button: 'primary',
    type: 'submit',
    requiresAuth: true,
  };
  const actionButtonProps = {
    button: 'alt',
  };
  const tipButtonProps = {
    ...actionButtonProps,
    disabled: !commentValue.length && !selectedSticker,
    tipSelectorOpen,
    activeTab,
    onClick: handleSelectTipComment,
  };
  const cancelButtonProps = {
    button: 'link',
    label: __('Cancel'),
  };
  const stickerReviewProps = {
    activeChannelUrl,
    src: selectedSticker ? selectedSticker.url : '',
    price: selectedSticker ? selectedSticker.price : 0,
    exchangeRate,
  };
  const commentSelectorElem = React.useMemo(
    () => (
      <CommentSelectors
        {...commentSelectorsProps}
        closeSelector={() =>
          setShowSelectors((prev) => ({
            tab: prev.tab || undefined,
            open: false,
          }))
        }
      />
    ),
    [commentSelectorsProps]
  );

  // **************************************************************************
  // Functions
  // **************************************************************************
  function handleJoinMembersOnlyChat() {
    return doOpenModal(MODALS.JOIN_MEMBERSHIP, {
      uri,
      fileUri,
    });
  }

  function handleSelectTipComment(tab: string) {
    setActiveTab(tab);

    if (isMobile) {
      setTipModalOpen(true);
      doOpenModal(MODALS.SEND_TIP, {
        uri,
        isTipOnly: true,
        hasSelectedTab: tab,
        customText: __('Preview Comment Tip'),
        setAmount: (amount, activeTab) => {
          setActiveTab(activeTab);
          setTipAmount(amount);
          setReviewingSupportComment(true);
        },
      });
    } else {
      setTipSelector(true);
    }

    if (onSlimInputClose) onSlimInputClose();
  }

  function handleStickerComment() {
    if (selectedSticker) {
      setReviewingStickerComment(false);
      setSelectedSticker(undefined);
      setShowSelectors({
        tab: SELECTOR_TABS.STICKER,
        open: true,
      });
    } else {
      setShowSelectors({
        tab: showSelectors.tab || undefined,
        open: !showSelectors.open,
      });
    }

    setTipSelector(false);
  }

  function handleCancelSticker() {
    setReviewingStickerComment(false);
    setSelectedSticker(null);
    setShowSelectors({
      tab: undefined,
      open: false,
    });
    if (onSlimInputClose) onSlimInputClose();
  }

  function handleImageUpload() {
    doOpenModal(MODALS.IMAGE_UPLOAD, {
      onUpdate: (imageUrl, imageTitle) => updateComment(imageUrl, imageTitle),
      assetName: __('Image'),
    });
  }

  function updateComment(imageUrl: string, imageTitle: string) {
    if (!imageTitle) imageTitle = '';
    let markdown = `![${imageTitle}](${imageUrl})`;
    setCommentValue((prev) => prev + (prev && prev.charAt(prev.length - 1) !== ' ' ? ` ${markdown} ` : `${markdown} `));
  }

  function handleCancelSupport() {
    if (!isReviewingSupportComment) setTipSelector(false);
    setReviewingSupportComment(false);

    if (stickerPrice) {
      setReviewingStickerComment(false);
      setShowSelectors({
        tab: showSelectors.tab || undefined,
        open: false,
      });
      setSelectedSticker(null);
    }

    if (onSlimInputClose) onSlimInputClose();
  }

  const getAmount = () => {
    if (activeTab === TAB_USD) {
      return tipAmount * 100; // pennies
    }
  };

  async function handleSupportComment() {
    if (!activeChannelClaimId) return;

    if (!channelClaimId) {
      doToast({
        message: __('Unable to verify channel settings. Try refreshing the page.'),
        isError: true,
      });
      return;
    }

    // do another creator settings fetch here to make sure that on submit, the setting did not change
    const commentsAreMembersOnly = await getCommentsMembersOnlyRestriction(
      claimId,
      channelClaimId,
      isLivestream,
      doFetchCreatorSettings
    );

    if (commentsAreMembersOnly === undefined) {
      doToast({
        message: __('Unable to send the comment.'),
        subMessage: __('Try again later, or refresh the page.'),
        isError: true,
      });
      return;
    }

    if (notAuthedToLiveChat && commentsAreMembersOnly) return handleJoinMembersOnlyChat();

    // if comment post didn't work, but tip was already made, try again to create comment
    if (commentFailure && tipAmount === successTip.tipAmount) {
      handleCreateComment(successTip.txid);
      return;
    } else {
      setSuccessTip({
        txid: undefined,
        tipAmount: undefined,
      });
    }

    // !! Beware of stale closure when editing the then-block, including doSubmitTip().
    doFetchCreatorSettings(channelClaimId)
      .then(() => {
        // const lockedMinAmount = minAmount; // value during closure.
        // const currentMinAmount = minAmountRef.current; // value from latest doFetchCreatorSettings().
        const lockedMinUSDAmount = minUSDAmount; // value during closure.

        const currentMinUSDAmount = minUSDAmountRef.current; // value from latest doFetchCreatorSettings().

        if (activeTab === TAB_USD && lockedMinUSDAmount !== currentMinUSDAmount) {
          doToast({
            message: __('The creator just updated the minimum setting. Please revise or double-check your tip amount.'),
            isError: true,
          });
          setReviewingSupportComment(false);
          return;
        }

        // look, this is crazy complex. I just put the dry run inside doSendTip() for USDC instead of here.
        if (activeTab === TAB_USD) {
          doSubmitTip();
          return;
        }

        // DryRun comment creation before submitting the tip
        handleCreateComment(undefined, undefined, undefined, undefined, true).then((res) => {
          if (res !== 'success') {
            setSubmitting(false);
            return;
          }

          doSubmitTip();
        });
      })
      .catch(() => {
        doToast({
          message: __('Unable to send the comment.'),
          subMessage: __('Try again later, or refresh the page.'),
          isError: true,
        });
      });
  }

  function doSubmitTip() {
    if (!claimId || !channelClaimId || !activeChannelName || !activeChannelClaimId || isSubmitting || !tipChannelName) {
      return;
    }

    setSubmitting(true);

    if (activeTab === TAB_USD) {
      const arweaveTipAddress = recipientArweaveTipInfo && recipientArweaveTipInfo.address;
      const transactionCurrency = activeTab === TAB_USD ? 'AR' : 'USD';
      const tipParams: ArTipParams = {
        tipAmountTwoPlaces: Math.round(tipAmount * 100) / 100,
        tipChannelName,
        channelClaimId,
        recipientAddress: arweaveTipAddress,
        currency: transactionCurrency,
      };
      const userParams: UserParams = {
        activeChannelName,
        activeChannelId: activeChannelClaimId,
      };
      const anonymous = false;
      // dryrun comment
      const dryRunCommentParams = {
        comment: commentValue,
        claim_id: claimId,
        parent_id: parentId,
        txid: undefined,
        payment_tx_id: activeTab === TAB_USD ? 'dummy_txid' : undefined,
        environment: stripeEnvironment,
        sticker: false,
        // dummy value for lint
        is_protected: Boolean(isLivestreamChatMembersOnly || areCommentsMembersOnly),
        amount: getAmount(),
        // dummy amount
        currency: transactionCurrency,
        // AR
        dry_run: true,
      };
      doCommentCreate(uri, isLivestream, dryRunCommentParams as any)
        .then((res: Record<string, any>) => {
          if (res && res.signature) {
            // tell apis about a tip, get a token and amount
            // make transaction
            // notify transaction id
            doArTip(tipParams, anonymous, userParams, claimId, stripeEnvironment)
              .then(
                (arTipResponse: {
                  transactionId: string;
                  currency: string;
                  referenceToken: string;
                  error?: string;
                }) => {
                  if (arTipResponse.error) {
                    throw new Error(arTipResponse.error);
                  }

                  const { transactionId } = arTipResponse;
                  const params = Object.assign({}, dryRunCommentParams);
                  params.payment_tx_id = transactionId;
                  params.dry_run = false;
                  params.amount = tipAmount; // dollars

                  // ...
                  handleCreateComment(null, null, transactionId, stripeEnvironment);
                  setCommentValue('');
                  setReviewingSupportComment(false);
                  setTipSelector(false);
                  setCommentFailure(false);
                  setSubmitting(false);
                }
              )
              .catch((e) => {
                // do the error handling
                doToast({
                  message: __('Tip failed to send.'),
                  subMessage: e?.message || e,
                  isError: true,
                });
                setSubmitting(false);
              });
          }
        })
        .catch((e) => {
          doToast({
            message: __('Comment failed to send.'),
            subMessage: e?.message || e,
            isError: true,
          });
          console.log('do commentcreate e', e);
          setSubmitting(false);
        });
    } else {
      const tipParams: TipParams = {
        tipAmount: Math.round(tipAmount * 100) / 100,
        tipChannelName,
        channelClaimId,
      };
      const userParams: UserParams = {
        activeChannelName,
        activeChannelId: activeChannelClaimId,
      };
      doSendCashTip(
        tipParams,
        false,
        userParams,
        claimId,
        stripeEnvironment,
        preferredCurrency,
        (customerTipResponse) => {
          const { payment_intent_id } = customerTipResponse;
          handleCreateComment(null, payment_intent_id, null, stripeEnvironment);
          setCommentValue('');
          setReviewingSupportComment(false);
          setTipSelector(false);
          setCommentFailure(false);
          setSubmitting(false);
        }
      );
    }
  }

  /**
   *
   * @param {string} [txid] Optional transaction id generated by
   * @param {string} [payment_intent_id] Optional payment_intent_id from Stripe payment
   * @param {string} [payment_tx_id] Optional payment_tx_id from Arweave payment
   * @param {string} [environment] Optional environment for Stripe (test|live)
   * @param {boolean} [dryRun] Optional flag to simulate the comment creation
   */
  async function handleCreateComment(
    txid?: any,
    payment_intent_id?: any,
    payment_tx_id?: any,
    environment?: any,
    dryRun = false
  ) {
    if (isSubmitting || disableInput || !claimId) return;
    // do another creator settings fetch here to make sure that on submit, the setting did not change
    const commentsAreMembersOnly = await getCommentsMembersOnlyRestriction(
      claimId,
      channelClaimId,
      isLivestream,
      doFetchCreatorSettings
    );

    if (commentsAreMembersOnly === undefined) {
      doToast({
        message: __('Unable to send the comment.'),
        subMessage: __('Try again later, or refresh the page.'),
        isError: true,
      });
      return;
    }

    if (notAuthedToLiveChat && commentsAreMembersOnly) return handleJoinMembersOnlyChat();
    setSubmitting(true);
    const stickerValue = selectedSticker && buildValidSticker(selectedSticker.name);
    return doCommentCreate(uri, isLivestream, {
      comment: stickerValue || commentValue,
      claim_id: claimId,
      parent_id: parentId,
      txid,
      payment_intent_id,
      payment_tx_id,
      environment,
      sticker: !!stickerValue,
      is_protected: Boolean(isLivestreamChatMembersOnly || areCommentsMembersOnly),
      amount: !!txid || !!payment_intent_id || !!payment_tx_id ? getAmount() : undefined,
      currency: 'AR',
      dry_run: dryRun,
    } as any)
      .then((res) => {
        setSubmitting(false);

        if (dryRun) {
          return res.comment_id ? 'success' : 'fail';
        }

        if (setQuickReply) setQuickReply(res);

        if (res && res.signature) {
          if (!stickerValue) setCommentValue('');
          setReviewingSupportComment(false);
          setTipSelector(false);
          setCommentFailure(false);

          if (onDoneReplying) {
            onDoneReplying();
          }
        }
      })
      .catch(() => {
        setSubmitting(false);

        if (dryRun) {
          return;
        }

        setCommentFailure(true);

        if (channelClaimId) {
          // It could be that the creator added a minimum tip setting.
          // Manually update for now until a websocket msg is available.
          doFetchCreatorSettings(channelClaimId).catch(() => {});
        }
      });
  }

  function handleSubmitSticker() {
    if (isReviewingSupportComment) {
      handleSupportComment();
    } else {
      handleCreateComment();
    }

    setSelectedSticker(null);
    setReviewingStickerComment(false);
    setShowSelectors({
      tab: showSelectors.tab || undefined,
      open: false,
    });
    setTipSelector(false);
  }

  // **************************************************************************
  // Effects
  // **************************************************************************
  React.useEffect(() => {
    // For refreshing
    const handleBack = (event) => {
      if (charCount > 0) {
        event.preventDefault();
        event.returnValue = '';
      }
    };

    BeforeUnload.register(handleBack, 'Creating comment');
    return () => {
      BeforeUnload.unregister(handleBack);
    };
  }, [charCount]);
  // Fetch channel constraints if not already.
  React.useEffect(() => {
    if (!channelSettings && channelClaimId) {
      doFetchCreatorSettings(channelClaimId).catch(() => {});
    }
  }, []);
  // eslint-disable-line react-hooks/exhaustive-deps
  // change sticker selection
  React.useEffect(() => {
    if (isMobile && showSelectors.tab && slimInputButtonRef && slimInputButtonRef.current) {
      slimInputButtonRef.current.click();
    }
  }, [isMobile, showSelectors.tab]);
  // Notifications: Fetch top-level comments to identify if it has been deleted and can reply to it
  React.useEffect(() => {
    if (shouldFetchComment && doCommentById) {
      doCommentById(parentId, false).then((result) => {
        setDeletedComment(String(result).includes('Error'));
      });
    }
  }, [doCommentById, shouldFetchComment, parentId]);
  // Stickers: Get LBC-USD exchange rate if hasn't yet and selected a paid sticker
  React.useEffect(() => {
    if (stickerPrice && !exchangeRate) Lbryio.getExchangeRates().then(({ LBC_USD }) => setExchangeRate(LBC_USD));
  }, [exchangeRate, stickerPrice]);
  React.useEffect(() => {
    if (recipientArweaveTipInfo === undefined) {
      doTipAccountCheckForUri(uri);
    }
  }, [recipientArweaveTipInfo, doTipAccountCheckForUri, uri]);
  // Handle keyboard shortcut comment creation
  React.useEffect(() => {
    function altEnterListener(e: any) {
      const inputEl = document.getElementById(isReply ? 'create__reply' : 'create__comment');

      if (inputEl && inputEl === document.activeElement) {
        const isTyping = Boolean(e.target.attributes['typing-term']);

        if (((isLivestream && !isTyping) || e.ctrlKey || e.metaKey) && e.keyCode === KEYCODES.ENTER) {
          e.preventDefault();
          buttonRef.current.click();
        }

        if (isLivestream && isTyping && e.keyCode === KEYCODES.ENTER) {
          const inputEl = document.getElementById(isReply ? 'create__reply' : 'create__comment');
          if (inputEl) inputEl.removeAttribute('typing-term');
        }
      }
    }

    window.addEventListener('keydown', altEnterListener);
    // removes the listener so it doesn't cause problems elsewhere in the app
    return () => {
      window.removeEventListener('keydown', altEnterListener);
    };
  }, [isLivestream]);
  // Determine my channels that have commented
  React.useEffect(() => {
    if (myCommentedChannelIds === undefined && claimId && myChannelClaimIds) {
      doFetchMyCommentedChannels(claimId);
    } // eslint-disable-next-line react-hooks/exhaustive-deps -- @see TODO_NEED_VERIFICATION
  }, [claimId, myCommentedChannelIds, myChannelClaimIds]);
  React.useEffect(() => {
    if (textInjection) {
      setCommentValue(
        commentValue === ''
          ? commentValue + textInjection + ' '
          : commentValue.substring(commentValue.length - 1) === ' '
            ? commentValue + textInjection + ' '
            : commentValue + ' ' + textInjection + ' '
      );
      requestAnimationFrame(() => {
        const cls = isReply ? 'create__reply' : 'create__comment';
        const textarea = document.querySelector<HTMLTextAreaElement>(
          `.${cls} textarea, textarea.${cls}, textarea#${cls}`
        );
        if (textarea) textarea.focus();
      });
    } // eslint-disable-next-line react-hooks/exhaustive-deps -- @see TODO_NEED_VERIFICATION
  }, [textInjection]);
  const notAuthedToLiveChat = Boolean(
    (isLivestream ? isLivestreamChatMembersOnly : areCommentsMembersOnly) && !userHasMembersOnlyChatPerk && !claimIsMine
  );
  let commentLabelText = 'Say something about this...';

  if (notAuthedToLiveChat) {
    commentLabelText = 'The creator has made this chat members-only';
  }

  // **************************************************************************
  // Render
  // **************************************************************************
  if (!isFetchingChannels && !hasChannels) {
    return (
      <div
        role="button"
        className="comment-create__auth"
        onClick={(e) => {
          e.preventDefault();
          e.stopPropagation();

          if (embed) {
            window.open(`https://odysee.com/$/${PAGES.AUTH}?redirect=/$/${PAGES.LIVESTREAM}`);
            return;
          }

          doOpenModal(MODALS.CONFIRM, {
            title: __('Channel is required for commenting'),
            subtitle: __("You'll need a channel to comment on this upload."),
            labelOk: __('Continue to channel creation'),
            onConfirm: (closeModal) => {
              const pathPlusRedirect = `/$/${PAGES.CHANNEL_NEW}?redirect=${pathname}`;

              if (isLivestream) {
                window.open(pathPlusRedirect);
              } else {
                navigate(pathPlusRedirect);
              }

              closeModal();
            },
          });
        }}
      >
        <FormField
          type="textarea"
          name="comment__signup-prompt"
          placeholder={__(commentLabelText)}
          disabled={isMobile}
        />

        {!isMobile && (
          <div className="section__actions--no-margin">
            <Button disabled button="primary" label={__('Send --[button to submit something]--')} requiresAuth />
          </div>
        )}
      </div>
    );
  }

  return (
    <>
      {notAuthedToLiveChat && (
        <ErrorBubble
          title={
            isLivestream ? __('This chat is in members-only mode') : __('This comment section is in members-only mode')
          }
          className="comment-restriction"
          subtitle={__(
            'To participate, consider buying a membership with the members-only chat perk from this creator!'
          )}
          action={<Button button="primary" label={__('Join')} onClick={handleJoinMembersOnlyChat} />}
        />
      )}

      <NavigationPrompt
        when={charCount > 0}
        message={__('You have not submitted your comment yet, are you sure you want to leave?')}
      />

      <Form
        onSubmit={() => {}}
        className={classnames('comment-create', {
          'comment-create--reply': isReply,
          'comment-create--nestedReply': isNested,
          'comment-create--bottom': bottom,
        })}
      >
        {isReviewingSupportComment ? (
          activeChannelUrl &&
          activeTab && (
            <>
              <TipReviewBox
                activeChannelUrl={activeChannelUrl}
                tipAmount={tipAmount}
                activeTab={activeTab}
                message={commentValue}
                isReviewingStickerComment={isReviewingStickerComment}
                stickerPreviewComponent={selectedSticker && <StickerReviewBox {...stickerReviewProps} />}
              />
              {arweaveTippingError && <div className={'error'}>{arweaveTippingError}</div>}
            </>
          )
        ) : selectedSticker ? (
          activeChannelUrl && <StickerReviewBox {...stickerReviewProps} />
        ) : (
          <>
            <FormField
              autoFocus={isReply}
              charCount={charCount}
              className={classnames('', {
                create__reply: isReply,
                create__comment: !isReply,
                disabled_chat_comments: notAuthedToLiveChat,
              })}
              disabled={isFetchingChannels || disableInput}
              isLivestream={isLivestream}
              label={<FormChannelSelector isReply={Boolean(isReply)} isLivestream={Boolean(isLivestream)} />}
              noticeLabel={
                (isMobile || isLivestream) && (
                  <HelpText
                    minAmount={minAmount}
                    minTip={minTip}
                    minSuper={minSuper}
                    deletedComment={deletedComment}
                    minUSDAmount={minUSDAmount}
                    minUSDSuper={minUSDSuper}
                    minUSDTip={minUSDTip}
                  />
                )
              }
              name={isReply ? 'create__reply' : 'create__comment'}
              onChange={(e) => setCommentValue(e.target.value)}
              handleTip={() => handleSelectTipComment(TAB_USD)}
              handleSubmit={handleCreateComment}
              slimInput={isMobile && !!uri} // "uri": make sure it's on a file page
              slimInputButtonRef={slimInputButtonRef}
              onSlimInputClose={onSlimInputClose}
              commentSelectorsProps={commentSelectorsProps}
              submitButtonRef={buttonRef}
              setShowSelectors={setShowSelectors as (arg0: { tab?: string; open: boolean }) => void}
              showSelectors={showSelectors}
              tipModalOpen={tipModalOpen}
              placeholder={__(commentLabelText)}
              quickActionHandler={undefined}
              quickActionLabel={undefined}
              textAreaMaxLength={isLivestream ? FF_MAX_CHARS_IN_LIVESTREAM_COMMENT : FF_MAX_CHARS_IN_COMMENT}
              type={'textarea'}
              value={commentValue}
              uri={uri}
            />
            {!isMobile && commentSelectorElem}
          </>
        )}

        {(!isMobile || isReviewingStickerComment) &&
          (tipSelectorOpen || (isReviewingStickerComment && stickerPrice)) && (
            <WalletTipAmountSelector
              activeTab={TAB_USD}
              amount={tipAmount}
              uri={uri} // convertedAmount={convertedAmount}
              customTipAmount={stickerPrice}
              exchangeRate={exchangeRate}
              fiatConversion={selectedSticker && !!selectedSticker.price}
              onChange={(amount) => setTipAmount(amount)}
              setDisableSubmitButton={setDisableReviewButton}
              setTipError={setTipError}
              tipError={tipError}
              isComment
            />
          )}

        {(!isMobile || isReviewingStickerComment || isReviewingSupportComment) && (
          <div className="section__actions">
            {/* Submit Button */}
            {isReviewingSupportComment && (
              <>
                {activeTab === TAB_USD && (
                  <Button
                    {...submitButtonProps}
                    autoFocus
                    disabled={disabled || !minAmountMet}
                    label={
                      isSubmitting
                        ? __('Sending...')
                        : commentFailure && tipAmount === successTip.tipAmount
                          ? __('Re-submit')
                          : __('Send')
                    }
                    onClick={handleSupportComment}
                  />
                )}
              </>
            )}
            {!isReviewingSupportComment && (
              <>
                {tipSelectorOpen ? (
                  <Button
                    {...submitButtonProps}
                    disabled={disabled || tipSelectorError || !minAmountMet || !canReceiveTips}
                    icon={ICONS.USD}
                    label={__('Review')}
                    onClick={() => {
                      setReviewingSupportComment(true);
                      if (onSlimInputClose) onSlimInputClose();
                    }}
                  />
                ) : (
                  <>
                    {(!isMobile || selectedSticker) && (!minUSDTip || claimIsMine) && (
                      <Button
                        {...submitButtonProps}
                        ref={buttonRef}
                        disabled={disabled}
                        label={
                          isLivestream
                            ? isSubmitting
                              ? __('Sending...')
                              : __('Send --[button to send chat message]--')
                            : isReply
                              ? isSubmitting
                                ? __('Replying...')
                                : __('Reply')
                              : isSubmitting
                                ? __('Commenting...')
                                : __('Comment --[button to submit something]--')
                        }
                        onClick={() =>
                          selectedSticker
                            ? handleSubmitSticker()
                            : handleCreateComment(undefined, undefined, undefined, undefined)
                        }
                      />
                    )}
                  </>
                )}
              </>
            )}

            {(!isMobile || isReviewingStickerComment) && (
              <>
                <StickerActionButton
                  {...actionButtonProps}
                  isReviewingStickerComment={isReviewingStickerComment}
                  icon={ICONS.STICKER}
                  onClick={handleStickerComment}
                  onChange={() => {}}
                  disabled={notAuthedToLiveChat}
                />

                {hasPremiumPlus && !isLivestream && (
                  <Button
                    button="alt"
                    icon={ICONS.IMAGE}
                    title={__('Upload Image')}
                    onClick={handleImageUpload}
                    onChange={() => {}}
                  />
                )}

                {!supportDisabled && !claimIsMine && (
                  <>
                    <TipActionButton
                      {...tipButtonProps}
                      name={__('AR')}
                      icon={ICONS.USD}
                      tab={TAB_USD}
                      disabled={tipButtonProps.disabled || activeArStatus !== 'connected'}
                    />
                  </>
                )}
              </>
            )}

            {tipSelectorOpen || isReviewingSupportComment ? (
              <Button {...cancelButtonProps} disabled={isSubmitting} onClick={handleCancelSupport} />
            ) : isReviewingStickerComment ? (
              <Button {...cancelButtonProps} onClick={handleCancelSticker} />
            ) : (
              onCancelReplying && <Button {...cancelButtonProps} onClick={onCancelReplying} />
            )}
            {!isLivestream && (
              <HelpText
                deletedComment={deletedComment}
                minAmount={minAmount}
                minTip={minTip}
                minSuper={minSuper}
                minUSDAmount={minUSDAmount}
                minUSDSuper={minUSDSuper}
                minUSDTip={minUSDTip}
              />
            )}
          </div>
        )}
        <div className="chat-resize">
          <div />
          <div />
          <div />
        </div>
      </Form>
    </>
  );
}

export default CommentCreate;
